#!/usr/bin/env node
// Usage: node cli.js <template.json> <start-date> [--csv] [--holidays 2026-12-25,2026-12-26]
const fs = require("fs");
const { buildPlan, toMarkdown, toCsv } = require("./src/plan");

const argv = process.argv.slice(2);
const csv = argv.includes("--csv");
const hIdx = argv.indexOf("--holidays");
const holidays = hIdx >= 0 ? String(argv[hIdx + 1] || "").split(",").filter(Boolean) : [];
const [templateFile, start] = argv.filter((a, i) => !a.startsWith("--") && !(hIdx >= 0 && i === hIdx + 1));

if (!templateFile || !start) {
  console.error("Usage: node cli.js <template.json> <start-date YYYY-MM-DD> [--csv] [--holidays d1,d2]");
  process.exit(2);
}

try {
  const template = JSON.parse(fs.readFileSync(templateFile, "utf8"));
  const plan = buildPlan(template, start, { holidays });
  console.log(csv ? toCsv(plan) : toMarkdown(plan, { role: template.role, start }));
} catch (e) {
  console.error(`Error: ${e.message}`);
  process.exit(1);
}

// Builds a dated onboarding plan from a role template and a start date.
// Task offsets are in WORKING days relative to day 1 (0 = first day,
// -3 = three working days before), so plans never land on weekends or
// listed public holidays.

const DAY_MS = 86400000;

function parseDate(iso) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(iso))) throw new Error(`Invalid date "${iso}" (use YYYY-MM-DD)`);
  const d = new Date(`${iso}T00:00:00Z`);
  if (Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== iso) throw new Error(`Invalid date "${iso}"`);
  return d;
}

const toISO = (d) => d.toISOString().slice(0, 10);

function isWorkday(d, holidays) {
  const dow = d.getUTCDay();
  return dow !== 0 && dow !== 6 && !holidays.has(toISO(d));
}

// Move `n` working days from `start` (negative = earlier).
function addWorkdays(start, n, holidays = new Set()) {
  let d = new Date(start.getTime());
  const step = n < 0 ? -1 : 1;
  let left = Math.abs(n);
  while (left > 0) {
    d = new Date(d.getTime() + step * DAY_MS);
    if (isWorkday(d, holidays)) left--;
  }
  return d;
}

function phaseOf(day) {
  if (day < 0) return "Before day 1";
  if (day === 0) return "Day 1";
  if (day < 5) return "Week 1";
  if (day < 20) return "First month";
  return "First 90 days";
}

function buildPlan(template, startISO, { holidays = [] } = {}) {
  const hol = new Set(holidays);
  const start = parseDate(startISO);
  if (!isWorkday(start, hol)) throw new Error(`Start date ${startISO} is a weekend or holiday`);
  if (!template || !Array.isArray(template.tasks) || template.tasks.length === 0) {
    throw new Error("Template needs a non-empty tasks list");
  }
  return template.tasks
    .map((t, i) => {
      if (!t.task || !t.owner || !Number.isInteger(t.day)) {
        throw new Error(`Task ${i + 1} needs task, owner and an integer day`);
      }
      return { due: toISO(addWorkdays(start, t.day, hol)), day: t.day, phase: phaseOf(t.day), owner: t.owner, task: t.task };
    })
    .sort((a, b) => a.day - b.day || a.owner.localeCompare(b.owner));
}

function toMarkdown(plan, { role = "New hire", start = "" } = {}) {
  const lines = [`# Onboarding plan: ${role}${start ? ` (starts ${start})` : ""}`];
  let phase = null;
  for (const t of plan) {
    if (t.phase !== phase) {
      phase = t.phase;
      lines.push("", `## ${phase}`, "");
    }
    lines.push(`- [ ] **${t.due}** · ${t.owner} — ${t.task}`);
  }
  return lines.join("\n");
}

// A cell starting with = + - @ (or a tab / carriage return) can be run as a
// formula when the CSV is opened in a spreadsheet. Prefixing a single quote
// makes spreadsheets treat it as text (the OWASP-recommended mitigation).
// The quote stays visible in plain-text viewers.
function neutralise(v) {
  const s = String(v);
  return /^[=+\-@\t\r]/.test(s) ? `'${s}` : s;
}

function csvCell(v) {
  const s = neutralise(v);
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

function toCsv(plan) {
  return ["due,phase,owner,task", ...plan.map((t) => [t.due, t.phase, t.owner, t.task].map(csvCell).join(","))].join("\n");
}

module.exports = { parseDate, addWorkdays, isWorkday, phaseOf, buildPlan, toMarkdown, toCsv, csvCell };

const test = require("node:test");
const assert = require("node:assert");
const { parseDate, addWorkdays, buildPlan, toMarkdown, toCsv, csvCell } = require("../src/plan");

const iso = (d) => d.toISOString().slice(0, 10);

test("working-day offsets skip weekends in both directions", () => {
  const mon = parseDate("2026-11-02"); // a Monday
  assert.strictEqual(iso(addWorkdays(mon, 0)), "2026-11-02");
  assert.strictEqual(iso(addWorkdays(mon, 4)), "2026-11-06"); // Friday
  assert.strictEqual(iso(addWorkdays(mon, 5)), "2026-11-09"); // next Monday
  assert.strictEqual(iso(addWorkdays(mon, -1)), "2026-10-30"); // previous Friday
});

test("holidays are skipped", () => {
  const mon = parseDate("2026-12-21");
  const hol = new Set(["2026-12-25"]);
  assert.strictEqual(iso(addWorkdays(mon, 4, hol)), "2026-12-28"); // Fri 25th skipped -> Mon 28th
});

test("plan is dated, phased and sorted by day", () => {
  const plan = buildPlan(
    { tasks: [{ day: 5, owner: "Manager", task: "Check-in" }, { day: -2, owner: "IT", task: "Laptop" }, { day: 0, owner: "HR", task: "Contract" }] },
    "2026-11-02"
  );
  assert.deepStrictEqual(
    plan.map((t) => [t.due, t.phase, t.task]),
    [
      ["2026-10-29", "Before day 1", "Laptop"],
      ["2026-11-02", "Day 1", "Contract"],
      ["2026-11-09", "First month", "Check-in"],
    ]
  );
});

test("bad input is rejected with a clear message", () => {
  assert.throws(() => buildPlan({ tasks: [{ day: 0, owner: "HR", task: "x" }] }, "2026-11-07"), /weekend or holiday/);
  assert.throws(() => buildPlan({ tasks: [] }, "2026-11-02"), /non-empty tasks/);
  assert.throws(() => buildPlan({ tasks: [{ day: 1.5, owner: "HR", task: "x" }] }, "2026-11-02"), /integer day/);
  assert.throws(() => parseDate("2026-02-30"), /Invalid date/);
});

test("csv cells that could run as spreadsheet formulas are neutralised", () => {
  for (const bad of ["=HYPERLINK(\"http://x\")", "+1+2", "-2+3", "@SUM(A1)", "\t=1", "\r=1"]) {
    assert.ok(csvCell(bad).replace(/^"/, "").startsWith("'"), `not neutralised: ${JSON.stringify(bad)}`);
  }
  assert.strictEqual(csvCell("=1+1"), "'=1+1");
  assert.strictEqual(csvCell("=A1,B1"), "\"'=A1,B1\""); // neutralised AND quoted
});

test("ordinary csv values are unchanged", () => {
  for (const ok of ["2026-11-02", "Day 1", "IT", "Order laptop", "a-b", "x=1", "email me@home", ""]) {
    assert.strictEqual(csvCell(ok), ok);
  }
});

test("a malicious template task cannot become a formula in the csv", () => {
  const plan = buildPlan({ tasks: [{ day: 0, owner: "@HR", task: "=cmd|' /C calc'!A0" }] }, "2026-11-02");
  const row = toCsv(plan).split("\n")[1];
  assert.strictEqual(row, "2026-11-02,Day 1,'@HR,'=cmd|' /C calc'!A0");
});

test("markdown groups by phase with checkboxes; csv quotes commas", () => {
  const plan = buildPlan({ tasks: [{ day: 0, owner: "HR", task: "Payroll, contract" }] }, "2026-11-02");
  assert.match(toMarkdown(plan, { role: "Engineer", start: "2026-11-02" }), /## Day 1\n\n- \[ \] \*\*2026-11-02\*\* · HR — Payroll, contract/);
  assert.strictEqual(toCsv(plan), 'due,phase,owner,task\n2026-11-02,Day 1,HR,"Payroll, contract"');
});
